const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);
p.colorMode(p.RGB, 1.0);
var fR, fG, fB;
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    fR =(p.sin(iX/10)*p.tan(iY/10))+((p.cos(5*iY*iX)/10)+(p.tan(50*iX*iY)/20))*8+(p.sin((p.pow(iX-250, 2)+p.pow(iY-230, 2))/100))*1.6;
    fG = (1/((p.pow(iX-250, 2)*p.pow(iY-230, 2))/100))*100*(p.tan(iX*iY*10000))*5;
    fB = (p.tan(iX+10.0)/p.sin(iY/10))*50-(p.sin(iX*iY)/p.cos(iX*iY)/10000);

    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
