const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);

//haikei no gurade-syon
for (var ix=0; ix<500; ix++)
{
  for (var iy=0; iy<500; iy++)
  {
    p.stroke(160+ix, 255-ix, 50);
    p.point(ix, iy);
  }
}

// haikei no namisen
p.strokeWeight(2);
for ( var f = 0; f < 500; f++ )
{
  var g = f*6;
  var h = (f*2);

  p.stroke(255, 0, 1110);
  p.line( g, f, f, h + h*p.cos( p.radians(g) ))  ;
}

//shiroi maru

p.strokeWeight(3);
for (var i= 0; i < 500; i+=8)
{
  for (var j= 0; j< 500; j+=25)
  {
    p.stroke(255);
    p.noFill();
    p.ellipse(i, j, 10 -i/20, 10 -i/20);
  }
}

for (var k= 0; k < 500; k+=10)
{
  for (var l= 0; l< 500; l+=6)
  {
    p.stroke(255);
    p.noFill();
    p.ellipse(l, k, 10 -l/20, 10 -l/20);
  }
}

  };
};

export default sketch;
