const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(50);
p5obj.colorMode(p5obj.RGB, 100);
p5obj.stroke(200);

var fx=0;
var fy=20;

for (var ix=0; ix<500; ix+=40)
{
  for (var iy=0; iy<500; iy+=40)
  {
    p5obj.noFill();
    p5obj.stroke(p5obj.random(0, 100), p5obj.random(0, 100), p5obj.random(0, 100));//譫邱夊牡
    p5obj.triangle(fx+ix, fy+iy, fx+10+ix, fy-20+iy, fx+ix+20, fy+iy);//荳雁髄縺阪・荳芽ｧ貞ｽ｢
    p5obj.triangle(fx+ix+5, fy+iy+10, fx+10+ix, fy+iy, fx+ix+15, fy+iy+10);//蜀・・縺ｮ荳芽ｧ貞ｽ｢
    p5obj.triangle(fx+iy, fy+ix, fx+10+iy, fy+20+ix, fx+iy+20, fy+ix);//荳句髄縺阪・荳芽ｧ貞ｽ｢
    p5obj.triangle(fx+iy+5, fy+ix-10, fx+10+iy, fy+ix, fx+iy+15, fy+ix-10);//蜀・・縺ｮ荳芽ｧ貞ｽ｢
  }
}

  };
};

export default sketch;
