// === リンク・スクロール系 ===

interface LinkProps {
  // Propsの型定義
  to: string; //hashで指定する
  from: string; // programming:pr, cgbasics: cg
  compId: number;
  //children: ReactNode; // children プロパティを追加
}

/**
 * アンカーリンクラッパー
 */
const LinkA: React.FC<LinkProps> = React.memo((props) => {
  const [toSamePage, setToSamePage] = useState<boolean>();
  const [canReturn, setCanReturn] = useState<boolean>(false);
  const [toURL, setToURL] = useState<string>(props.to);
  const [linkLabel, setLinkLabel] = useState<string>();

  useEffect(() => {

    let resultItem: AnchorItem | undefined;
    let ltoURL: string = "";

    if( props.from === "pr" )
    {
      resultItem = findAnchorItemByHash(props.to,AnchorItemProgramming);
      ltoURL = "/programming/";
    }
    else if( props.from === "cg" )
    {
      ltoURL = "/cgbasics/";
      resultItem = findAnchorItemByHash(props.to,AnchorItemCgbasics);
    }
    

    if( resultItem !== undefined )
    {
      // マッチングした
      console.log(` props.compId, resultItem.compId.toString() in LinkA: ${props.compId}, ${resultItem.compId.toString()}`);

      const ltoSamePage = ( props.compId === resultItem.compId );
      setToSamePage( ltoSamePage );
      setLinkLabel( resultItem.label );

      // 授業ID
      if( ltoSamePage )
      {
        ltoURL = `#${props.to}`;
      }
      else
      {
        ltoURL +=  `${resultItem.compId.toString()}-0-0#${resultItem.hash}`;
      }
      setToURL(ltoURL);
    }
    
    //setToSamePage();
    
  }, [props]);

  useEffect(() => {
     setCanReturn(true);
  }, [toURL]);


  if (canReturn) {
    return (
//</Link>        toSamePage ? <HashLink className="scroll-link" to={toURL} smooth={true} scroll={el => scrollWithOffset(el)}>{linkLabel}</HashLink>
        toSamePage ? <HashLink className="scroll-link" to={toURL} smooth={true} scroll={el => scrollWithOffset(el)}>{linkLabel}</HashLink>
                    : <HashLink to={toURL} target="_blank">{linkLabel}</HashLink>
    );
  } else {
    return (<p>※アンカーマッチング失敗 to: {props.to}</p>);
  }
}, (prevProps, nextProps) => {
  // falseの時再レンダリング
  return prevProps.to === nextProps.to;
  //return false;
});

export default LinkA;


interface AnchorItem {
  hash: string;
  label: string;
  compId: number;
}
const findAnchorItemByHash = (hashToFind: string, list: AnchorItem[]): AnchorItem | undefined => {
  return list.find((item) => item.hash === hashToFind);
};

/**
 * ページアクセス直後のスクロール 
 */
 export const JumpToDefaultScroll = (afterS: number, location: any) => {

  // ハッシュ#がある場合それ優先
  const currentHash = window.location.hash;
  const decodedHash = decodeURIComponent(currentHash);
  const hashParts = decodedHash.split('#');

  if( hashParts.length > 2 )
  {
    const lastHashPart = hashParts[hashParts.length - 1];
    console.log( `lastHashPart: ${lastHashPart}` );
    jumpToElement(lastHashPart);
  }
  else
  {
    // セクションリンク
    const practiceSId: string = "s" + afterS;
    console.log(`URL Scroll practiceId: ${practiceSId}`);
    
    jumpToElement( practiceSId );
  }
};
/**
 * スクロールなしでジャンプ 
 */
const jumpToElement = (elementId: string) => {
  const element = document.getElementById(elementId);
  //console.log(`element in jumpToElement: ${element}`);

  if( element )
  {
    if( elementId === "s0" )
    {
      //console.log("JumpToDefaultScroll : 0");
      window.scrollTo(0, 0);
    }
    else
    {
      window.scrollTo({
        top: element.getBoundingClientRect().top + window.scrollY - 60,
        behavior: 'auto',
      });
    }
  }
  else
  {
    //console.log("JumpToDefaultScroll : 0");
    window.scrollTo(0, 0);
  }
};
/**
 * スクロール有りリンク 
 */
const scrollWithOffset = (el: HTMLElement | null) => {
  if (el) {
    window.scrollTo({
      top: el.getBoundingClientRect().top + window.scrollY - 60,
      behavior: 'smooth',
    });
  }
};

/**
 * igm（キャプション付き） 
 */
const sketchImageRoot: string = process.env.PUBLIC_URL + '/images';
interface ImgProps {
  src: string;
  caption?: string;
}
export const Img: React.FC<ImgProps> = ({ src, caption }) => {

  const fileNameWithExtension = src.split('/').pop(); // ファイル名と拡張子が含まれた文字列を取得
  const fileName = fileNameWithExtension?.split('.').slice(0, -1).join('.'); // 拡張子を除いたファイル名を取得

  return (
    <figure className="figure">
      <img src={`${sketchImageRoot}${src}`} alt={fileName} />
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
};

