const sketch = (p5obj:any) => {
/**真ん中の線がミリ秒を、中心から２本目の線が秒を、三本目の線が分を表している。
 四本目の線は１時間ごとにひとつずれる。*/
 let ms: number = 0;
 let s: number = 0;
 let m: number = 0;
 let h: number = 0;
let lastSecond: number = 0;
let iFrameCur: number;


p5obj.setup = () =>  {
  p5obj.createCanvas(1000, 1000);
  iFrameCur = 0;
  p5obj.frameRate(60);
  p5obj.background(0);
}
p5obj.draw = () =>  {
  ms = p5obj.millis() % 1000;
  s = p5obj.second();
  m = p5obj.minute();
  h = p5obj.hour();


  p5obj.fill(0, 4);
  p5obj.noStroke();
  p5obj.rect(0, 0, p5obj.width, p5obj.height);

  p5obj.noFill();
  p5obj.translate(p5obj.width/2, p5obj.height/2);

  p5obj.push();
  let ms_deg: number = 360 / 1000.0 * ms;//中心の線の回転の大きさ
  p5obj.stroke(255);
  p5obj.rotate( p5obj.radians( ms_deg ) );
  p5obj.line(0, 0, 0, p5obj.height / 30);//中心からの距離
  p5obj.pop();

  p5obj.push();

  p5obj.stroke(255);
  p5obj.rotate( p5obj.radians(s*(360/60)) );//二本目の線の回転の大きさ
  p5obj.line(0, 80, 0, p5obj.height/20);//中心からの距離
  p5obj.pop();

  p5obj.push();
  p5obj.stroke(255);
  p5obj.rotate( p5obj.radians(m*(360/60)) );//三本目の線の回転の大きさ
  p5obj.line(0, 160, 0, p5obj.height / 10);//中心からの距離
  p5obj.pop();

  p5obj.push();
  p5obj.stroke(255);
  p5obj.rotate( p5obj.radians(h*(360/12)));//四本目の線の回転の大きさ
  p5obj.line(0, 200, 0, p5obj.height / 3);//中心からの距離
  p5obj.pop();
}
//https://yoppa.org/proga10/1419.html https://yoppa.org/proga10/1429.htmlを参考に制作。
//時間を表す線を円形に配置し、差別化を図った。

};

export default sketch;
