const sketch = (p5obj:any) => {
p5obj.setup = () => 
{ 
  p5obj.createCanvas(1000, 1000);  
  p5obj.colorMode(p5obj.RGB, 100, 100, 100, 100);
  p5obj.background(1, 1, 1);
  p5obj.strokeCap(p5obj.ROUND);//線を丸く
  fire( 250, 180, 700, 50, 10);
}
const fire = (x: number, y: number, l: number, a: number, iLevel: number) => { 
  p5obj.strokeWeight(2);
  p5obj.stroke(95, 30, 20, 3);
  let X: number = x+l*p5obj.sin(p5obj.radians(a)); 
  let Y: number = y+l*p5obj.cos(p5obj.radians(a)); 
  let X2: number = x+l*p5obj.sin(p5obj.radians(a)); 
  let Y2: number = y+l*p5obj.cos(p5obj.radians(a)); 
  p5obj.line( X, Y, x, y ); 
  p5obj.line( X2, Y2, x, y );
  if( iLevel>0 )  
  {    
    fire( X, Y, l*0.3, a+150, iLevel-1);
    fire( X, Y, l*0.7, a-150, iLevel-1);
    fire( X2, Y2, l*0.3, a+20, iLevel-1);
    fire( X2, Y2, l*0.7, a-50, iLevel-1);
  }
}

};

export default sketch;
